boltOn.example:
t3template.addControl({ id: 'lowcut', label: 'Low Cut Hz', type: 'slider', min: 20, max: 300, step: 5, default: 80, panel: 'Master' });
t3template.addControl({ id: 'bass', label: 'Bass dB', type: 'slider', min: -12, max: 12, step: 0.5, default: 3, panel: 'Master' });
t3template.addControl({ id: 'gate', label: 'Gate dB', type: 'slider', min: -80, max: -20, step: 1, default: -60, panel: 'Master' });
t3template.addControl({ id: 'loudness', label: 'Loudness', type: 'select', options: [{ value: 0, label: 'Off' }, { value: -16, label: 'Podcast -16 LUFS' }, { value: -14, label: 'Music -14 LUFS' }], default: -16, panel: 'Master' });
// Heard while playing AND rendered: a low cut, then a bass shelf.
t3template.addAudioFilter('tone', (c) => [
  { type: 'highpass', frequency: c.lowcut },
  { type: 'lowshelf', frequency: 120, gain: c.bass },
]);
// Render only, after the tone filters: a gate, then loudness normalisation last.
t3template.addExportNote((edl, c) => ({
  audioFilter: [
    c.gate > -80 ? `agate=threshold=${(10 ** (c.gate / 20)).toFixed(5)}:ratio=2` : '',
    c.loudness ? `loudnorm=I=${c.loudness}:TP=-1.5:LRA=11` : '',
  ].filter(Boolean).join(','),
  note: `Master: low cut ${c.lowcut} Hz, bass ${c.bass} dB, gate ${c.gate} dB, loudness ${c.loudness || 'off'}`,
}));
t3template.addEdlTransform((edl) => ({ ...edl, regions: edl.regions.filter((r) => r.endSec - r.startSec >= 0.25) }));
t3template.addToolbarButton('Mark Beat', (t) => t.actions.addMarker(undefined, 'Beat'), { shortcut: 'b' });
